import author_pilot as a
import json
a.qs.clear()
def lesson(doc,page,question,options,correct,explanation,tf,truth,tfex,third,choices,answers,thirdex):
 a.add(doc,page,'single_choice',question,correct,explanation,options)
 a.add(doc,page,'true_false',tf,truth,tfex)
 a.add(doc,page,'multiple_choice',third,answers,thirdex,choices)
lesson('p1-d02',12,'Trước khi đề xuất một chatbot, câu hỏi nào bám đúng bước chẩn đoán của slide?', ['Nên chọn model có nhiều tham số nhất nào?','Người dùng gặp khó khăn ở công đoạn nào?','Nên làm landing page màu gì?','Có thể bỏ qua quy trình hiện tại không?'],'b','Bắt đầu từ khó khăn, người quá tải, quy trình hiện tại và đối tượng phục vụ.','Theo slide, chỉ cần thấy một công việc lặp lại là có thể đề xuất giải pháp ngay, dù chưa hiểu điểm đau.',False,'Slide kết luận chưa thấu hiểu điểm đau thì chưa đề xuất giải pháp.','Những lăng kính nào được dùng để tìm bài toán AI? (Chọn tất cả đáp án đúng.)',['Công việc lặp lại cần chuẩn hóa','Thời gian hao phí cho tìm kiếm/đọc hiểu/chờ đợi','Chỉ số tham số của model lớn nhất','Bắt buộc thay mọi quy trình bằng chatbot'],['a','b'],'Slide liệt kê lặp lại, tốn thời gian, lợi thế AI và điểm đau.')
lesson('p1-d04',9,'Agent lặp vô hạn vì thiếu điều kiện dừng. Lớp nào trực tiếp quyết định quy tắc lặp và dừng?', ['Prompt engineering','Context engineering','Loop engineering','Chỉ UI styling'],'c','Loop engineering quy định lặp thế nào và dừng khi nào.','Trong mô hình bốn lớp, context engineering quyết định model được thấy gì trong một lần gọi.',True,'Đây là mô tả trực tiếp của lớp context.','Những nội dung nào thuộc harness engineering trên bản đồ bốn lớp? (Chọn tất cả đáp án đúng.)',['Sandbox','Quyền và trace','Chỉ câu chữ trong một message','Chỉ gói token của một lần gọi'],['a','b'],'Harness là runtime với tool, sandbox, quyền và trace.')
lesson('p1-d10',5,'Vì sao lỗi corpus RAG có thể khó phát hiện hơn lỗi dashboard bị vỡ?', ['RAG luôn ném exception khi dùng chunk cũ','Câu trả lời có thể dùng chunk lỗi thời mà không phát sinh exception','Mọi dashboard luôn chính xác','Corpus chỉ cần đúng chủ đề, không cần mới'],'b','Slide gọi đây là silent failure: hệ thống vẫn trả lời dù chunk stale hoặc mâu thuẫn bản mới.','Hợp đồng đúng đắn của RAG chỉ yêu cầu chunk liên quan chủ đề, không cần xét freshness.',False,'Chunk cần vừa liên quan vừa không stale/không bị bản mới hơn mâu thuẫn.','Những tín hiệu nào cần xét cho chunk được truy xuất theo slide? (Chọn tất cả đáp án đúng.)',['Liên quan chủ đề','Không lỗi thời hoặc mâu thuẫn với bản mới hơn','Chỉ có nhiều từ giống câu hỏi','Chỉ là file mở được'],['a','b'],'Đây là hai phần của hợp đồng đúng đắn cho retrieval.')
lesson('p1-d12',10,'Agent cần giữ bộ nhớ qua nhiều lần gọi nhưng vẫn tuân thủ stateless processes. Cách nào phù hợp?', ['Giữ tất cả state chỉ trong RAM một instance','Externalize state ra bên ngoài instance','Hardcode state vào image','Tắt health check'],'b','Stateless không cấm memory; slide yêu cầu externalize state.','Config in env đồng nghĩa với hardcode API key trong mã để dễ deploy.',False,'Slide nêu config in env và không hardcode API keys.','Những mục nào nằm trong deployment checklist của slide? (Chọn tất cả đáp án đúng.)',['Health check endpoint','Graceful shutdown','Xóa toàn bộ structured logging','Chỉ kiểm tra giao diện trên máy lập trình viên'],['a','b'],'Checklist gồm secrets management, health check, structured logging, monitoring endpoint và graceful shutdown.')
lesson('p1-d13',9,'Hệ thống cần trả lời một câu hỏi mới về failure mode chưa từng gặp mà không deploy code mới. Khái niệm nào phù hợp?', ['Chỉ monitoring cho known-knowns','Observability','Chỉ ping endpoint','Chỉ alert cố định'],'b','Observability là thuộc tính cho phép đặt câu hỏi mới bằng telemetry đủ giàu.','Monitoring được slide mô tả là theo dõi các câu hỏi và failure mode đã biết trước.',True,'Monitoring dùng dashboard/alert dựng sẵn cho known-knowns.','Những loại telemetry nào được nêu để hỗ trợ observability? (Chọn tất cả đáp án đúng.)',['Metrics','Logs và traces','Chỉ bản chụp giao diện','Chỉ danh sách phiên bản trình duyệt'],['a','b'],'Nguồn liệt kê metrics + logs + traces.')
lesson('p1-d15',11,'Nhóm có GPU server và ưu tiên inference throughput cao. Công cụ nào được slide gợi ý?', ['Ollama chỉ để thay DNS','vLLM','Một spreadsheet giá token','Chỉ nén source code'],'b','vLLM được mô tả production-grade inference, PagedAttention và continuous batching.','Slide mô tả Ollama phù hợp cho dev, demo và edge deployment với thiết lập đơn giản.',True,'Đây là các trường hợp dùng Ollama được ghi trên slide.','Khi so sánh chi phí self-host với cloud API, cần tính những khoản nào ngoài token? (Chọn tất cả đáp án đúng.)',['GPU','Ops và maintenance','Chỉ màu giao diện','Chỉ số lượng dòng README'],['a','b'],'Lưu ý của slide yêu cầu tính cả GPU, ops và maintenance; không mặc định self-host rẻ hơn.')
lesson('p1-d03',14,'Trong Agentic Fit, tiêu chí nào hỏi bước tiếp theo có phụ thuộc kết quả vừa quan sát không?', ['Long Horizon','Dynamic Decision','Chỉ độ dài prompt','Chỉ số lượng người dùng'],'b','Dynamic Decision đánh giá việc quyết định bước tiếp theo từ quan sát mới.','Tool Interaction đánh giá hệ thống có cần gọi search, API, database hoặc các công cụ khác không.',True,'Slide liệt kê trực tiếp các ví dụ tool này.','Những tiêu chí nào thuộc bộ bốn Agentic Fit? (Chọn tất cả đáp án đúng.)',['Multi-step Reasoning','Long Horizon','Màu avatar agent','Số slide trong tài liệu'],['a','b'],'Bốn tiêu chí gồm multi-step reasoning, tool interaction, dynamic decision và long horizon.')
lesson('p1-d05',9,'Vì sao chỉ đáp ứng functional job có thể chưa đủ cho sản phẩm AI?', ['Người dùng không có cảm xúc hay nhu cầu xã hội','Sản phẩm có thể đúng chức năng nhưng không được dùng lại','Chỉ cần model lớn là đủ','JTBD chỉ xét chi phí GPU'],'b','Slide yêu cầu xét việc cần làm, cảm giác mong muốn và cách người dùng muốn được nhìn nhận.','Mong muốn cảm thấy tự tin hơn, ít sợ sai hơn thuộc nhu cầu được slide đưa vào JTBD.',True,'Nguồn nêu trực tiếp các nhu cầu cảm xúc này.','Những câu hỏi nào thuộc JTBD trên slide? (Chọn tất cả đáp án đúng.)',['Người dùng muốn hoàn thành việc gì?','Người dùng muốn được nhìn nhận ra sao?','Model có bao nhiêu layer?','GPU mang nhãn hiệu nào?'],['a','b'],'JTBD xét việc cần làm, cảm xúc và cách được nhìn nhận.')
lesson('p1-d06',10,'Một AI feature đã chạy được nhưng thiếu fallback và monitoring. Theo Definition of Done, đánh giá nào đúng?', ['Đã done vì code chạy','Chưa đủ điều kiện done','Chỉ cần thêm logo','Không cần quality threshold'],'b','Done phải có quality threshold, latency, fallback và monitoring signal.','Backlog AI nên xem xét cả feature debt, data debt và technical debt.',True,'Ba loại debt này được slide liệt kê.','Những điều kiện nào được dùng trong ví dụ support agent đã done? (Chọn tất cả đáp án đúng.)',['Citation coverage đủ','Escalation path rõ và test set đạt ngưỡng','Chỉ demo một câu trả lời hay','Chỉ có public URL'],['a','b'],'Ví dụ nguồn nêu citation coverage, escalation và test set đạt ngưỡng.')
lesson('p1-d07',13,'Tài liệu có heading và section tốt; cần chunk trọn ý và metadata section rõ. Strategy nào phù hợp nhất trong bảng?', ['Fixed-size không xét cấu trúc','Heading/structural','Cắt ngẫu nhiên từng ký tự','Chỉ chia theo kích thước file'],'b','Heading/structural cắt theo Markdown heading/section, giữ ý và metadata section.','Fixed-size đơn giản và dễ kiểm soát cost nhưng có thể cắt giữa câu hoặc bảng.',True,'Bảng ghi ưu/nhược này cho fixed-size.','Những nhận định nào đúng về recursive chunking trong bảng? (Chọn tất cả đáp án đúng.)',['Cố gắng tôn trọng ranh giới tự nhiên','Vẫn có thể phải cắt nếu một đoạn quá dài','Bảo đảm không bao giờ cắt đoạn','Chỉ áp dụng cho hình ảnh'],['a','b'],'Recursive là mặc định tốt nhưng vẫn có giới hạn khi đoạn vượt kích thước.')
lesson('p1-d08',14,'Trường hợp nào có lý do rõ để dùng RAG theo slide?', ['Brainstorm tự do không cần corpus/citation','Tra cứu policy nội bộ thay đổi và cần nguồn kiểm chứng','Chỉ tạo thơ từ trí tưởng tượng','Không có corpus riêng và prompt đã đủ'],'b','Dữ liệu nội bộ thay đổi và yêu cầu citation là lý do dùng RAG.','Slide cho rằng mọi câu hỏi kiến thức chung đều bắt buộc phải dùng RAG.',False,'Kiến thức chung LLM đã biết được xếp vào nhóm chưa cần RAG.','Những trường hợp nào được slide xếp vào nhóm chưa cần RAG? (Chọn tất cả đáp án đúng.)',['Không có corpus riêng để truy xuất','Prompt engineering đơn giản đã đủ','Cần cập nhật policy nội bộ liên tục và kiểm chứng nguồn','Cần giảm hallucination có hệ thống với corpus sẵn có'],['a','b'],'Bảng phân biệt nhu cầu RAG với trường hợp giải pháp đơn giản đã đủ.')
lesson('p1-d09',11,'Hai subagent khám phá hai hướng độc lập, còn kết quả cuối là một sản phẩm chung. Cách tổ chức nào phù hợp nguyên tắc slide?', ['Song song cả mọi thao tác ghi cùng file','Song song việc đọc, tuần tự hóa việc ghi chung','Chỉ cho phép một agent đọc mọi nguồn','Không cần điều phối ghi'],'b','Khám phá độc lập có thể song song; ghi vào sản phẩm chung nên có một luồng.','Nguyên tắc trên slide khuyên nhiều subagent đồng thời ghi vào một sản phẩm chung mà không điều phối.',False,'Nguồn nêu tuần tự hóa việc ghi vào sản phẩm chung.','Những việc nào phù hợp với nguyên tắc song song hóa việc đọc? (Chọn tất cả đáp án đúng.)',['Khám phá các hướng độc lập','Đọc bằng chứng riêng rồi hợp nhất có điều phối','Nhiều agent sửa cùng một sản phẩm tùy ý','Bỏ mọi bước tổng hợp kết quả'],['a','b'],'Nguồn phân biệt khám phá độc lập với ghi vào sản phẩm chung.')
